def cmd_list(args, stdin):
    start = parse_day(args.from_date) if args.from_date else None
    end = parse_day(args.to_date) if args.to_date else None
    if args.from_date and start is None:
        print(f"日期 {args.from_date!r} 认不出来，请用 YYYY-MM-DD，例如 2026-09-08。")
        return 2
    if args.to_date and end is None:
        print(f"日期 {args.to_date!r} 认不出来，请用 YYYY-MM-DD，例如 2026-09-08。")
        return 2
    if start and end and start > end:
        print("起始日期不能晚于结束日期。")
        return 2

    conditions = []
    params = []
    if start:
        conditions.append("occurred_on >= ?")
        params.append(start)
    if end:
        conditions.append("occurred_on <= ?")
        params.append(end)
    where = f" WHERE {' AND '.join(conditions)}" if conditions else ""
    conn = connect(args.db)
    rows = conn.execute(
        f"SELECT * FROM notes{where} ORDER BY occurred_on DESC, id DESC LIMIT ?",
        [*params, args.limit],
    ).fetchall()
    if not rows:
        if start or end:
            print("这段时间里没有记录。")
        else:
            print("还没有任何记录。用 add 存一条，或用 import 把已有的文件导进来。")
        return 0
    for row in rows:
        print(note_heading(row))
    return 0
